using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.JNT.JuntaDetalle{    [SwaggerSchema("Modelo de lectura de un JuntaDetalle")]    [GraphQLDescription("Objeto que representa un JuntaDetalle existente.")]    public class clReadJuntaDetalle    {        [SwaggerSchema("Identificador único del JuntaDetalle")]        [GraphQLDescription("Identificador único del JuntaDetalle")]        public int? JuntaDetalleID { get; set; }        [SwaggerSchema("JuntaID")]        [GraphQLDescription("JuntaID")]        public int? JuntaID { get; set; }        [SwaggerSchema("Contenido")]        [GraphQLDescription("Contenido")]        public string? Contenido { get; set; } = default!;        [SwaggerSchema("FechaRegistro")]        [GraphQLDescription("FechaRegistro")]        public DateTime? FechaRegistro { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un JuntaDetalle")]    [GraphQLDescription("Input para crear un JuntaDetalle.")]    public class clCreateJuntaDetalle    {        [GraphQLNonNullType] [SwaggerSchema("JuntaID")]        [GraphQLDescription("JuntaID")]        public int JuntaID { get; set; }        [GraphQLNonNullType] [SwaggerSchema("Contenido")]        [GraphQLDescription("Contenido")]        public string Contenido { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("FechaRegistro")]        [GraphQLDescription("FechaRegistro")]        public DateTime FechaRegistro { get; set; }        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un JuntaDetalle")]    [GraphQLDescription("Input para actualizar parcialmente un JuntaDetalle.")]    public class clUpdateJuntaDetalle    {        [SwaggerSchema("Identificador único del JuntaDetalle")]        [GraphQLDescription("Identificador único del JuntaDetalle")]        public int? JuntaDetalleID { get; set; }        [SwaggerSchema("JuntaID")]        [GraphQLDescription("JuntaID")]        public int? JuntaID { get; set; }        [SwaggerSchema("Contenido")]        [GraphQLDescription("Contenido")]        public string? Contenido { get; set; }        [SwaggerSchema("FechaRegistro")]        [GraphQLDescription("FechaRegistro")]        public DateTime? FechaRegistro { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}